package com.aetheris.workflow.service;
import com.aetheris.workflow.security.V2WorkflowFixture;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
class WorkflowAuthorizationServiceTest {
 @Test void instanceUsesPersistedParentResourceNotOwnerOrTriggeringActor() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForList(contains("SELECT task_id"),eq(Long.class),eq(19L))).thenReturn(List.of(8L));var service=new WorkflowAuthorizationService(jdbc,f.authorization);f.request(r->{assertTrue(service.canReadInstance("alice",19));f.allowed.set(false);assertFalse(service.canReadInstance("alice",19));});var batches=f.requests.stream().filter(r->r.operation().equals("auth.permission.batch")).toList();assertEquals(2,batches.size());assertEquals(8,batches.getFirst().body().path("items").get(0).path("resourceId").asLong());assertEquals("view",batches.getFirst().body().path("action").asText());}}
 @Test void pipelineNeedsEveryActualNodeAndExecuteIsDistinctFromRead() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForList(contains("SELECT target_task_id"),eq(Long.class),eq(1L),eq(1L))).thenReturn(List.of(8L,9L));var service=new WorkflowAuthorizationService(jdbc,f.authorization);f.request(r->{f.batchAllowed=Set.of(8L,9L);assertTrue(service.canReadPipeline("alice",1));f.batchAllowed=Set.of(8L);assertFalse(service.canExecutePipeline("alice",1));});var batches=f.requests.stream().filter(r->r.operation().equals("auth.permission.batch")).toList();assertEquals(List.of("view","execute"),batches.stream().map(r->r.body().path("action").asText()).toList());assertTrue(batches.stream().allMatch(r->!r.body().has("username")));}}
 @Test void noContextBareUsernameAndSubstitutedAdminCannotTriggerAuthOrDatabase() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);var service=new WorkflowAuthorizationService(jdbc,f.authorization);assertFalse(service.canReadInstance("admin",1));assertFalse(service.canStartPipeline("admin",1));assertFalse(service.canExecuteInstance("admin",1));assertFalse(service.mayManage("admin"));f.request(r->{assertFalse(service.canReadPipeline("admin",1));assertFalse(service.canStartPipeline("admin",1));assertFalse(service.mayManage("admin"));});verifyNoInteractions(jdbc);assertEquals(1,f.requests.size());}}
 @Test void currentDependencyClosureRequiresAllPermissionsAndEmptyClosureNeverAllows() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForList(contains("WITH RECURSIVE"),eq(Long.class),eq(1L))).thenReturn(List.of(8L,9L));when(jdbc.queryForList(contains("WITH RECURSIVE"),eq(Long.class),eq(2L))).thenReturn(List.of());var service=new WorkflowAuthorizationService(jdbc,f.authorization);f.request(r->{assertFalse(service.canStartPipeline("alice",1));f.batchAllowed=Set.of(8L,9L);assertTrue(service.canStartPipeline("alice",1));assertFalse(service.canStartPipeline("alice",2));f.manage.set(true);assertTrue(service.mayManage("alice"));assertFalse(service.mayManage("admin"));});}}
 @Test void dependencyPermissionChecksUseAtMostFiveHundredItemsPerBatch() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);var service=new WorkflowAuthorizationService(jdbc,f.authorization);var ids=java.util.stream.LongStream.rangeClosed(1,501).boxed().toList();f.batchAllowed=Set.copyOf(ids);f.request(r->assertTrue(service.canExecuteTasks("alice",ids)));var batches=f.requests.stream().filter(r->r.operation().equals("auth.permission.batch")).toList();assertEquals(List.of(500,1),batches.stream().map(r->r.body().path("items").size()).toList());verifyNoInteractions(jdbc);}}
 @Test void outOfScopeBatchResultCannotPermitAnyPipelineAndInvalidIdsNeverSendPermissionRequest() throws Exception {try(var f=new V2WorkflowFixture()){var jdbc=mock(JdbcTemplate.class);var service=new WorkflowAuthorizationService(jdbc,f.authorization);f.request(r->{assertFalse(service.canExecuteTasks("alice",List.of(0L)));assertFalse(service.canExecuteTasks("alice",List.of()));f.outsideBatch=true;var error=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.canExecuteTasks("alice",List.of(8L)));assertEquals(503,error.getStatusCode().value());});assertEquals(1,f.requests.stream().filter(r->r.operation().equals("auth.permission.batch")).count());verifyNoInteractions(jdbc);}}

}
